const today = new Date();
today.setHours(0, 0, 0, 0);

const webHookBaseUrl = "https://your-n8n-instance.com/webhook/task-update"; // Replace with your webhook URL

return $input.all().map(item => {
  const row = item.json;
  const deadline = new Date(row.Deadline);
  deadline.setHours(0, 0, 0, 0);

  const diffTime = deadline - today;
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

  let daysText = "";
  if (diffDays < 0) {
    daysText = `⚠️ OVERDUE by ${Math.abs(diffDays)} day(s)`;
  } else if (diffDays === 0) {
    daysText = "⏳ Due Today!";
  } else {
    daysText = `🗓️ ${diffDays} day(s) remaining`;
  }

  const updateLink = `${webHookBaseUrl}?taskId=${encodeURIComponent(row['Task ID'])}`;

  return {
    json: {
      taskId: row['Task ID'],
      task: row.Task,
      category: row.Category || 'Daily Action Plan',
      owner: row.Owner,
      email: row.Email,
      whatsapp: row.WhatsApp,
      deadline: row.Deadline,
      status: row.Status,
      diffDays: diffDays,
      daysText: daysText,
      updateLink: updateLink
    }
  };
});

