parameters.jsCode:
const items = $input.all();

const todayStr = new Date().toLocaleDateString('en-GB');

let summaryText = `Dear Efe,\n\n`;

summaryText += `Please find below the Engineering Daily Operational Review action items for ${todayStr}.\n\n`;

const tasksByOwner = {};

items.forEach(item => {
  const owner = item.json.Owner || 'Unassigned';

  if (!tasksByOwner[owner]) {
    tasksByOwner[owner] = [];
  }

  tasksByOwner[owner].push(item.json);
});


for (const owner in tasksByOwner) {

  summaryText += `${owner}\n`;
  summaryText += `--------------------\n`;

  tasksByOwner[owner].forEach(task => {

    summaryText += `• ${task.Task}\n`;
    summaryText += `Deadline: ${task.Deadline}\n\n`;

  });

  summaryText += `\n`;

}


summaryText += `Please review and follow up on pending actions during the next operational review.\n\n`;

summaryText += `Regards,\nEngineering Operations`;


return [{
  json: {
    summaryText,
    managerEmail: "giwamodupe@outlook.com",
    managerWhatsApp: "whatsapp:+2347064018988"
  }
}];

const today = new Date();
today.setHours(0, 0, 0, 0);

const items = $input.all();
const overdueTasks = [];
const employeeEmailsToCc = new Set();

const managerEmail = "giwamodupe@outlook.com";     // Replace with Efe's email
const managerWhatsApp = "2348044444444";   // Replace with Efe's WhatsApp number

// Robust date parser for DD-MMM-YYYY or YYYY-MM-DD
function parseDeadline(dateStr) {
  if (!dateStr) return null;
  if (typeof dateStr === 'string' && dateStr.includes('-')) {
    const parts = dateStr.split('-');
    if (parts.length === 3 && isNaN(parts[1])) {
      const months = { jan:0, feb:1, mar:2, apr:3, may:4, jun:5, jul:6, aug:7, sep:8, oct:9, nov:10, dec:11 };
      const day = parseInt(parts[0], 10);
      const month = months[parts[1].toLowerCase()];
      const year = parseInt(parts[2], 10);
      return new Date(year, month, day);
    }
  }
  return new Date(dateStr);
}

items.forEach(item => {
  const row = item.json;

  // Check status (flexible case matching)
  const statusVal = row.Status || row.status || '';
  if (statusVal.toLowerCase() !== 'open') return;

  const rawDeadline = row.Deadline || row.deadline;
  const deadline = parseDeadline(rawDeadline);

  if (!deadline || isNaN(deadline.getTime())) return;

  deadline.setHours(0, 0, 0, 0);

  const diffTime = deadline - today;
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

  // Filter: Overdue by 1 day or more (diffDays < 0)
  if (diffDays < 0) {
    const daysOverdue = Math.abs(diffDays);
    const ownerEmail = row.Email || row.email || '';

    overdueTasks.push({
      taskId: row['Task ID'] || row['taskId'] || row['Task ID '] || 'N/A',
      task: row.Task || row.task,
      owner: row.Owner || row.owner || 'Unassigned',
      email: ownerEmail,
      whatsapp: row.WhatsApp || row.whatsapp,
      deadline: rawDeadline,
      daysOverdue: daysOverdue
    });

    if (ownerEmail) {
      employeeEmailsToCc.add(ownerEmail);
    }
  }
});

// If no items are overdue, return empty array (stops workflow gracefully)
if (overdueTasks.length === 0) {
  return [];
}

const todayStr = today.toLocaleDateString('en-GB');
const ccEmailsString = Array.from(employeeEmailsToCc).join(';');

let alertText = `🚨 DAILY OVERDUE ESCALATION REPORT - ${todayStr}\n\nDear Efe,\n\nThe following open action item(s) are overdue by 1 day or more:\n\n`;
let alertHtml = `<h2>🚨 Daily Overdue Escalation Report (${todayStr})</h2><p>Dear Efe,</p><p>The following open action item(s) are overdue by 1 day or more:</p><ul>`;

overdueTasks.forEach((t, idx) => {
  alertText += `${idx + 1}. [${t.taskId}] ${t.task}\n   • Owner: ${t.owner}\n   • Deadline: ${t.deadline}\n   • Status: ⚠️ Overdue by ${t.daysOverdue} day(s)\n\n`;

  alertHtml += `<li><strong>[${t.taskId}] ${t.task}</strong><br/>`;
  alertHtml += `<strong>Owner:</strong> ${t.owner}<br/>`;
  alertHtml += `<strong>Original Deadline:</strong> ${t.deadline}<br/>`;
  alertHtml += `<span style="color:red;">⚠️ Overdue by ${t.daysOverdue} day(s)</span></li><br/>`;
});

alertText += `Cc: ${Array.from(employeeEmailsToCc).join(', ')}\n\nPlease resolve or update these items.`;
alertHtml += `</ul><p><em>This email has been CC'd to the responsible team members listed above.</em></p>`;

return [
  {
    json: {
      managerEmail: managerEmail,
      ccEmails: ccEmailsString,
      managerWhatsApp: managerWhatsApp,
      overdueCount: overdueTasks.length,
      subject: `ESCALATION ALERT: ${overdueTasks.length} Overdue Action Item(s)`,
      alertText: alertText,
      alertHtml: alertHtml
    }
  }
];
